package com.pulselens.analytics.security;import com.pulselens.analytics.repository.UserRepository;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.*;import org.springframework.stereotype.Service;import java.util.List;
@Service public class DatabaseUserDetailsService implements UserDetailsService{private final UserRepository users;public DatabaseUserDetailsService(UserRepository users){this.users=users;}public UserDetails loadUserByUsername(String email){var u=users.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("Invalid email or password."));return User.withUsername(u.getEmail()).password(u.getPasswordHash()).authorities(List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole()))).disabled(!u.isAccountEnabled()).build();}}
